#!/usr/bin/env bash
# seed-test-data.sh
# Bulk-indexes ~55 synthetic DMARC aggregate records into OpenSearch.
# Covers: passes, SPF/DKIM failures, unaligned-but-passing, quarantine/reject,
#          several IPs, several domains, multiple reporting orgs.
#
# Usage:
#   export OPENSEARCH_URL=https://172.105.135.195:9200
#   export OPENSEARCH_USER=admin
#   export OPENSEARCH_PASSWORD=<password>
#   bash scripts/seed-test-data.sh
#
# Expected pass-rate hand-calculation:
#   Total message_count (passed_dmarc:true) = 2633
#   Total message_count (all)               = 3108
#   Pass rate = 2633 / 3108 * 100 = 84.72%

set -euo pipefail

OS_URL="${OPENSEARCH_URL:-https://172.105.135.195:9200}"
OS_USER="${OPENSEARCH_USER:-admin}"
OS_PASS="${OPENSEARCH_PASSWORD:?Set OPENSEARCH_PASSWORD}"

INDEX_2026_10_04="dmarc_aggregate-2026-10-04"
INDEX_2026_10_03="dmarc_aggregate-2026-10-03"
INDEX_2026_10_02="dmarc_aggregate-2026-10-02"
INDEX_2026_10_01="dmarc_aggregate-2026-10-01"

# Apply index template first
echo "==> Applying index template..."
curl -sk -X PUT "${OS_URL}/_index_template/dmarc_aggregate_template" \
  -u "${OS_USER}:${OS_PASS}" \
  -H 'Content-Type: application/json' \
  -d @opensearch/index-template.json
echo ""

# Build the bulk payload
BULK_FILE=$(mktemp)
trap 'rm -f "${BULK_FILE}"' EXIT

cat > "${BULK_FILE}" << 'BULK_END'
